def validate_qasm_file(qasm_path: str | Path) -> Path:
    """Validate that a QASM file exists and contains parseable content."""
    path = Path(qasm_path)
    if not path.exists():
        raise FileNotFoundError(f"DNA circuit file not found: {path}")

    text = path.read_text(encoding="utf-8").strip()
    if not text:
        raise ValueError(f"DNA circuit file is empty: {path}")

    if not text.startswith("OPENQASM"):
        raise ValueError(f"DNA circuit file is not valid OpenQASM: {path}")

    return path


