import { QuantumState, TelemetryData } from '../models/quantum';

/**
 * Calculate process fidelity using the same phenomenological model as the backend.
 *
 * F_p = F_base + log(DD + 1) * 0.015 - (eta - 1) * 0.05 + log10(N / 15000) * 0.005
 */
export function calculateProcessFidelity(
  baseFidelity: number,
  ddLoops: number,
  noiseFactor: number,
  tomographyStates: number = 15000
): number {
  const ddImprovement = Math.log(ddLoops + 1) * 0.015;
  const noisePenalty = (noiseFactor - 1) * 0.05;
  const tomographyImprovement = Math.log10(tomographyStates / 15000) * 0.005;
  return Math.min(
    0.9999,
    Math.max(0.5, baseFidelity + ddImprovement - noisePenalty + tomographyImprovement)
  );
}

/**
 * Calculate QBER using the same model as the backend.
 *
 * QBER = Q_base + dark_count_rate * 1e4 * 0.01 + (0.2 * L_channel / 100) * 0.01
 */
export function calculateQBER(
  baseQBER: number,
  darkCountRate: number,
  channelLength: number
): number {
  const darkCountPenalty = darkCountRate * 1e4 * 0.01;
  const channelLossPenalty = ((0.2 * channelLength) / 100) * 0.01;
  return Math.min(0.5, Math.max(0.01, baseQBER + darkCountPenalty + channelLossPenalty));
}

/**
 * Estimate a noise factor from tomography sample size.
 * This is a local-only heuristic used when the backend is unavailable.
 */
export function calculateNoiseFactor(
  baseNoise: number,
  tomographyStates: number,
  environmentalStress: number = 1.0
): number {
  const tomographyImprovement = Math.log10(tomographyStates / 15000) * 0.1;
  return Math.max(1.0, baseNoise - tomographyImprovement) * environmentalStress;
}

export function generateTelemetryData(state: QuantumState, timeOffset: number = 0): TelemetryData {
  const timestamp = Date.now() + timeOffset;
  const jitter = (Math.random() - 0.5) * 0.02;

  return {
    timestamp,
    processFidelity: state.processFidelity + jitter,
    qber: state.qber + Math.abs(jitter) * 0.5,
    noiseFactor: state.noiseFactor + jitter * 0.1,
    channelDelay: state.channelLength * 5 + Math.random() * 2,
  };
}

export function simulateFidelityOverTime(
  baseFidelity: number,
  steps: number,
  noiseAmplitude: number = 0.02
): number[] {
  const results: number[] = [];
  let currentFidelity = baseFidelity;

  for (let i = 0; i < steps; i++) {
    const noise = (Math.random() - 0.5) * noiseAmplitude;
    const drift = Math.sin(i * 0.1) * 0.01;
    currentFidelity = Math.max(0.5, Math.min(0.9999, currentFidelity + noise + drift));
    results.push(currentFidelity);
  }

  return results;
}

export function calculateSecurityScore(
  fidelity: number,
  qber: number,
  noiseFactor: number,
  timeoutCompliance: number
): number {
  const fidelityScore = fidelity * 30;
  const qberScore = (1 - qber) * 30;
  const noiseScore = (2 - noiseFactor) * 20;
  const timeoutScore = timeoutCompliance * 20;

  return Math.min(100, Math.max(0, fidelityScore + qberScore + noiseScore + timeoutScore));
}

export function assessThreatLevel(
  qber: number,
  noiseFactor: number
): 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL' {
  if (qber < 0.05 && noiseFactor < 1.2) return 'LOW';
  if (qber < 0.08 && noiseFactor < 1.4) return 'MEDIUM';
  if (qber < 0.11 && noiseFactor < 1.6) return 'HIGH';
  return 'CRITICAL';
}

export function formatMetric(value: number, type: 'fidelity' | 'qber' | 'noise' | 'time'): string {
  switch (type) {
    case 'fidelity':
      return `${(value * 100).toFixed(2)}%`;
    case 'qber':
      return `${(value * 100).toFixed(2)}%`;
    case 'noise':
      return `${value.toFixed(2)}x`;
    case 'time':
      return `${value.toFixed(0)} ms`;
    default:
      return value.toFixed(2);
  }
}

export function getMetricColor(value: number, type: 'fidelity' | 'qber' | 'noise'): string {
  switch (type) {
    case 'fidelity':
      if (value >= 0.95) return '#10b981';
      if (value >= 0.9) return '#06b6d4';
      if (value >= 0.85) return '#f59e0b';
      return '#ef4444';
    case 'qber':
      if (value <= 0.05) return '#10b981';
      if (value <= 0.08) return '#06b6d4';
      if (value <= 0.11) return '#f59e0b';
      return '#ef4444';
    case 'noise':
      if (value <= 1.1) return '#10b981';
      if (value <= 1.3) return '#06b6d4';
      if (value <= 1.5) return '#f59e0b';
      return '#ef4444';
    default:
      return '#06b6d4';
  }
}

